from typing import List

def pluck(arr: List[int]) -> List[int]:
    if not arr:
        return []

    smallest_even = float('inf')
    smallest_index = -1

    for i, value in enumerate(arr):
        if value % 2 == 0 and value < smallest_even:
            smallest_even = value
            smallest_index = i

    if smallest_index == -1:
        return []

    return [smallest_even, smallest_index]
